def subtreeSizes(parent):
    n = len(parent)
    children = [[] for _ in range(n)]
    root = 0
    for v, p in enumerate(parent):
        if p == -1:
            root = v
        else:
            children[p].append(v)
    order = [root]
    for u in order:  # BFS: parents appear before their children
        order.extend(children[u])
    size = [1] * n
    for u in reversed(order):
        if parent[u] != -1:
            size[parent[u]] += size[u]
    return size
